function file_video(i, e, t, n, a, c, l, d, o) {
  const UI = window.UI || {}, player_config = window.player_config || {};
  o = o || [];
  const s = a.includes(".m3u8") || c === "application/x-mpegURL";
  let r = "", p = "", g = "";

  if (!UI.disable_player) {
    if (player_config.player === "plyr") {
      r = `<video id="player" playsinline controls autoplay data-poster="${n}">
              <source src="${a}" type="${s ? "application/x-mpegURL" : "video/mp4"}">
              ${o.map(h => `<track kind="subtitles" src="${escHtml(h.url)}" label="${escHtml(h.label)}" default>`).join("")}
            </video>`;
      p = "https://cdn.plyr.io/" + player_config.plyr_io_version + "/plyr.polyfilled.js";
      g = "https://cdn.plyr.io/" + player_config.plyr_io_version + "/plyr.css";
    } else if (player_config.player === "videojs") {
      r = `<video id="vplayer" poster="${n}" class="video-js vjs-default-skin vjs-big-play-centered" controls autoplay preload="auto" width="100%" height="100%" data-setup='{"fluid":true,"autoplay":true,"fullscreen":true}'>
              <source src="${a}" type="${s ? "application/x-mpegURL" : "video/mp4"}">
              <source src="${a}" type="video/webm">
              ${o.map(h => `<track kind="subtitles" src="${escHtml(h.url)}" label="${escHtml(h.label)}" default>`).join("")}
            </video>`;
      p = "https://vjs.zencdn.net/" + player_config.videojs_version + "/video.js";
      g = "https://vjs.zencdn.net/" + player_config.videojs_version + "/video-js.css";
    } else if (player_config.player === "dplayer") {
      r = '<div id="player-container" style="width:100%;height:auto;"></div>';
      p = "https://cdn.jsdelivr.net/npm/dplayer/dist/DPlayer.min.js";
      g = "https://cdn.jsdelivr.net/npm/dplayer/dist/DPlayer.min.css";
    } else if (player_config.player === "jwplayer") {
      r = '<div id="player" style="width:100%;"></div>';
      p = "https://content.jwplatform.com/libraries/IDzF9Zmk.js";
    }
  }

  const f = `<div class="gdi-player-wrap" style="width:100%;max-width:1400px;margin:0 auto;background:#000;">
    ${r}
  </div>
  <div id="gdi-playlist-wrap" style="margin-top:16px;display:none;">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;">
      <strong style="font-size:14px;"><i class="bi bi-collection-play me-2"></i>Playlist</strong>
      <span id="gdi-playlist-count" style="font-size:12px;color:var(--gdi-text-muted,#aaa);"></span>
    </div>
    <div id="gdi-playlist-list" style="max-height:240px;overflow-y:auto;border:1px solid rgba(255,255,255,0.12);border-radius:8px;padding:6px;background:rgba(0,0,0,0.2);"></div>
  </div>`;

  const u = UI.disable_video_download ? "" : renderDownloadButtons(a, e, { showMedia: true });
  $("#content").html(_viewerCard('<i class="bi bi-camera-video-fill gdi-icon-video"></i>', i, t, f, u));
  $(".gdi-viewer").css({ "max-width": "1400px", "width": "98%", "margin": "0 auto" });

  if (g) {
    const h = document.createElement("link");
    h.rel = "stylesheet";
    h.href = g;
    document.head.appendChild(h);
  }

  window._gdiPlayerInstance = null;
  let playlistVideos = [], currentIndex = -1;

  function initPlayerEvents() {
    if (player_config.player === "plyr") {
      const m = new Plyr("#player", { autoplay: true, keyboard: { focused: true, global: true }, controls: ["play-large", "play", "progress", "current-time", "mute", "volume", "captions", "settings", "pip", "airplay", "fullscreen"] });
      window._gdiPlayerInstance = m;
      m.on("ready", () => {
        m.play().catch(() => { });
      });
      m.on("ended", () => playNextInPlaylist());
    } else if (player_config.player === "videojs") {
      const m = videojs("vplayer", {
        autoplay: true,
        playbackRates: [0.5, 0.75, 1, 1.25, 1.5, 2],
        controlBar: {
          pictureInPictureToggle: true,
          fullscreenToggle: true,
          currentTimeDisplay: true,
          timeDivider: true,
          durationDisplay: true,
          progressControl: true,
          volumePanel: true
        }
      });
      window._gdiPlayerInstance = m;
      m.ready(function () {
        this.play().catch(() => { });
        // Ativar autoplay adequadamente
        this.autoplay(true);
        
        // Controles do teclado
        this.el().addEventListener("keydown", function (v) {
          if (v.target.tagName !== "INPUT") {
            if (v.key === " ") {
              v.preventDefault();
              m.paused() ? m.play() : m.pause();
            } else if (v.key === "f" || v.key === "F") {
              m.isFullscreen() ? m.exitFullscreen() : m.requestFullscreen();
            } else if (v.key === "m" || v.key === "M") {
              m.muted(!m.muted());
            } else if (v.key === "ArrowRight") {
              m.currentTime(m.currentTime() + 10);
            } else if (v.key === "ArrowLeft") {
              m.currentTime(Math.max(0, m.currentTime() - 10));
            } else if (v.key === "ArrowUp") {
              m.volume(Math.min(1, m.volume() + 0.1));
            } else if (v.key === "ArrowDown") {
              m.volume(Math.max(0, m.volume() - 0.1));
            }
          }
        });
      });
      m.on("ended", () => playNextInPlaylist());
    } else if (player_config.player === "dplayer") {
      const m = new DPlayer({
        container: document.getElementById("player-container"),
        autoplay: true,
        screenshot: true,
        video: {
          url: a,
          pic: n,
          type: s ? "hls" : "auto"
        },
        subtitle: o.length ? { url: o[0].url, type: "webvtt" } : undefined,
        fullscreen: true
      });
      window._gdiPlayerInstance = m;
      m.play();
      m.on("ended", () => playNextInPlaylist());
    } else if (player_config.player === "jwplayer") {
      const m = jwplayer("player").setup({
        file: a,
        type: c,
        autostart: true,
        image: n,
        width: "100%",
        aspectratio: "16:9",
        title: i,
        description: "Powered by Google Drive Index",
        controls: true,
        tracks: o.map(v => ({ file: v.url, kind: "captions", label: v.label, default: true })),
        captions: { color: "#f3f378", fontSize: 14, backgroundOpacity: 50, edgeStyle: "raised" }
      });
      window._gdiPlayerInstance = m;
      m.on("complete", () => playNextInPlaylist());
    }
  }

  function renderPlaylistUI() {
    if (!playlistVideos.length) return;
    let h = "";
    playlistVideos.forEach((m, v) => {
      const w = v === currentIndex;
      const y = w ? "background:var(--bs-primary,#1f6feb);color:#fff;" : "background:rgba(255,255,255,0.05);color:var(--gdi-text,#e6edf3);";
      h += `<div class="gdi-playlist-item" data-idx="${v}" style="padding:8px 12px;margin:3px 0;border-radius:6px;cursor:pointer;display:flex;align-items:center;justify-content:space-between;font-size:13px;transition:background 0.2s;${y}">
        <div style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:80%;">
          <i class="bi bi-${w ? "play-fill" : "film"} me-2"></i>
          <span style="font-weight:${w ? "600" : "400"};">${escHtml(m.name)}</span>
        </div>
        <span style="font-size:11px;opacity:0.8;">${m.size || ""}</span>
      </div>`;
    });
    $("#gdi-playlist-list").html(h);
    $("#gdi-playlist-count").text(`${currentIndex + 1} / ${playlistVideos.length}`);
    $("#gdi-playlist-wrap").show();
    $(".gdi-playlist-item").off("click").on("click", function () {
      const m = parseInt($(this).data("idx"));
      if (!isNaN(m) && playlistVideos[m]) {
        switchVideo(m);
      }
    });
  }

  function switchVideo(h) {
    if (h < 0 || h >= playlistVideos.length) return;
    currentIndex = h;
    const m = playlistVideos[currentIndex];

    if (m.pageUrl) {
      history.pushState(null, m.name, m.pageUrl);
    }

    $(".gdi-file-header-name").text(m.name);
    $(".gdi-file-header-meta").text(m.size);

    const v = window.drive_names ? window.drive_names[window.current_drive_order || 0] : "Drive";
    $("title").html(`${v} - ${m.name}`);

    if (!UI.disable_video_download) {
      $(".gdi-viewer-footer").html(renderDownloadButtons(m.streamUrl, encodeURIComponent(m.name), { showMedia: true }));
    }

    // Definir source do vídeo para cada player
    if (player_config.player === "plyr" && window._gdiPlayerInstance) {
      window._gdiPlayerInstance.source = {
        type: "video",
        title: m.name,
        sources: [{
          src: m.streamUrl,
          type: m.streamUrl.includes(".m3u8") || m.mimeType === "application/x-mpegURL" ? "application/x-mpegURL" : "video/mp4"
        }]
      };
      // Garantir que começa a tocar
      setTimeout(() => {
        window._gdiPlayerInstance.play().catch(() => { });
      }, 100);
    } else if (player_config.player === "videojs" && window._gdiPlayerInstance) {
      window._gdiPlayerInstance.src({
        src: m.streamUrl,
        type: m.streamUrl.includes(".m3u8") || m.mimeType === "application/x-mpegURL" ? "application/x-mpegURL" : "video/mp4"
      });
      // Garantir autoplay
      window._gdiPlayerInstance.autoplay(true);
      setTimeout(() => {
        window._gdiPlayerInstance.play().catch(() => { });
      }, 100);
    } else if (player_config.player === "dplayer" && window._gdiPlayerInstance) {
      window._gdiPlayerInstance.switchVideo({
        url: m.streamUrl,
        pic: m.poster,
        type: m.streamUrl.includes(".m3u8") || m.mimeType === "application/x-mpegURL" ? "hls" : "auto"
      });
      window._gdiPlayerInstance.play();
    } else if (player_config.player === "jwplayer" && window._gdiPlayerInstance) {
      window._gdiPlayerInstance.load([{
        file: m.streamUrl,
        type: m.mimeType,
        image: m.poster,
        title: m.name
      }]);
      window._gdiPlayerInstance.play();
    } else {
      // Fallback para player nativo HTML5
      const w = document.getElementById("player") || document.getElementById("vplayer");
      if (w) {
        w.src = m.streamUrl;
        w.autoplay = true;
        w.play().catch(() => { });
      }
    }

    renderPlaylistUI();
  }

  function playNextInPlaylist() {
    if (currentIndex >= 0 && currentIndex < playlistVideos.length - 1) {
      switchVideo(currentIndex + 1);
    }
  }

  // Carregar playlist de vídeos da pasta
  const folderPath = window.location.pathname.split("/").slice(0, -1).join("/") + "/";
  requestListPath(folderPath, {}, function (h) {
    if (!h || !h.data || !h.data.files) return;
    const m = h.data.files;
    playlistVideos = [];

    m.forEach(v => {
      if (FILE_TYPES.video.includes(v.fileExtension) || (v.mimeType && v.mimeType.includes("video"))) {
        const w = encodeURIComponent(v.name);
        const y = UI.second_domain_for_dl ? UI.downloaddomain + v.link : window.location.origin + v.link;
        const _ = folderPath + w + "?a=view";
        const b = v.thumbnailLink ? v.thumbnailLink.replace("s220", "s0") : UI.poster;
        playlistVideos.push({
          id: v.id,
          name: v.name,
          size: formatFileSize(v.size),
          streamUrl: y,
          pageUrl: _,
          mimeType: v.mimeType,
          poster: b
        });
      }
    });

    // Encontrar índice do vídeo atual
    currentIndex = playlistVideos.findIndex(v => v.name === i || v.streamUrl === a);

    if (currentIndex === -1 && playlistVideos.length > 0) {
      playlistVideos.unshift({
        name: i,
        size: t,
        streamUrl: a,
        pageUrl: window.location.href,
        mimeType: c,
        poster: n
      });
      currentIndex = 0;
    }

    renderPlaylistUI();
  }, null);

  // Carregar biblioteca do player
  if (p) {
    if (window.Plyr || window.videojs || window.DPlayer || window.jwplayer) {
      initPlayerEvents();
    } else {
      const h = document.createElement("script");
      h.src = p;
      h.onload = initPlayerEvents;
      document.head.appendChild(h);
    }
  }
}

// ============= FUNÇÕES DE ÁUDIO =============
function file_audio(i, e, t, n, a, c, l) {
  const UI = window.UI || {};
  l = l || [{ name: i, url: n, cover: UI.audioposter }];
  const d = UI.disable_player ? "" : '<div id="aplayer-container" style="max-width:680px;margin:0 auto;"></div>';
  const o = UI.disable_audio_download ? "" : renderDownloadButtons(n, e, { showMedia: true });

  if ($("#content").html(_viewerCard('<i class="bi bi-music-note-beamed gdi-icon-audio"></i>', i, t, d, o)), UI.disable_player)
    return;

  const s = document.createElement("link");
  s.rel = "stylesheet";
  s.href = "https://cdn.jsdelivr.net/npm/aplayer@1.10.1/dist/APlayer.min.css";
  document.head.appendChild(s);

  const r = document.createElement("script");
  if (r.src = "https://cdn.jsdelivr.net/npm/aplayer@1.10.1/dist/APlayer.min.js", r.onload = function () {
    window._gdiAPlayer = new APlayer({
      container: document.getElementById("aplayer-container"),
      mini: false,
      autoplay: true,
      theme: "#4d9fec",
      loop: "all",
      order: "list",
      preload: "auto",
      volume: 0.7,
      listFolded: false,
      audio: l
    });
  }, document.head.appendChild(r), l.length <= 1) {
    const p = window.location.pathname.split("/").slice(0, -1).join("/") + "/";
    requestListPath(p, {}, function (g) {
      if (!g || !g.data || !g.data.files) return;
      const f = g.data.files.filter(u => FILE_TYPES.audio.includes(u.fileExtension));
      if (f.length > 1) {
        const u = f.map(m => ({
          name: m.name,
          url: UI.second_domain_for_dl ? UI.downloaddomain + m.link : window.location.origin + m.link,
          cover: UI.audioposter
        }));
        window._gdiAPlayer && window._gdiAPlayer.destroy();
        window._gdiAPlayer = new APlayer({
          container: document.getElementById("aplayer-container"),
          mini: false,
          autoplay: true,
          loop: "all",
          order: "list",
          preload: "auto",
          volume: 0.7,
          audio: u
        });
        const h = u.findIndex(m => m.url === n);
        if (h > 0) {
          window._gdiAPlayer.list.switch(h);
        }
      }
    }, null);
  }
}
